entries[223955] = { ["name"] = "Recipe: Fine Egg Powder", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Fine Egg Powder.\nRecipe for 5 servings. Actual number of servings will vary based on cooking skill.\nRequires Khaz Algar Cooking (35)\nSell Price:\nFine Egg Powder\nCrafting Reagent\n\"Ground by someone with the Cooking skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[223956] = { ["name"] = "Recipe: Everything-on-a-Stick", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Everything-on-a-Stick.\nRecipe for 2 servings. Actual number of servings will vary based on cooking skill.\nRequires Khaz Algar Cooking (35)\nSell Price:\nEverything-on-a-Stick\nBinds when picked up\nUse: Restores ( 375000 / 5 * 20) health over 20 sec. Must remain seated while eating.\n\nWell Fed\nIf you spend at least 10 seconds eating you will become Well Fed and a gain the stats equivalent to a random Khaz Algar Meal.\n\"Could be anything!\"\nSell Price:\nRequires Coagulated Yolk" }
entries[223957] = { ["name"] = "Recipe: Protein Slurp", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Protein Slurp.\nRecipe for 1 servings. Actual number of servings will vary based on cooking skill.\nRequires Khaz Algar Cooking (35)\nSell Price:\nProtein Slurp\nUse: Restores ( 375000 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\n\nWell Fed\nIf you spend at least 10 seconds eating you will become Well Fed gaining [source value] of your lowest secondary stat and increase your size by 1% for 15 min.\n\"It bubbles.\"\nSell Price:\nRequires Fine Egg Powder (5)", ["unresolvedValues"] = true }
