entries[224007] = { ["name"] = "Uses for Leftover Husks (How to Take Them Apart)", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Skinning Knowledge by 10.\nRequires Khaz Algar Skinning (1)\n\"A somewhat detailed guide to using what's left after an arachnoid consumes its prey. Mildly useful to skinners, disgusting for all.\"\nSell Price:" }
