entries[224023] = { ["name"] = "Herbal Embalming Techniques", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 10.\nRequires Khaz Algar Herbalism (1)\n\"A small book describing how to use rare herbs from Khaz Algar and Northrend to perfectly preserve a corpse to retain its flavor. Could be useful for herbalists.\"\nSell Price:" }
