entries[224025] = { ["name"] = "Crackling Shard", ["text"] = "Binds to Warband\nUnique (10)\nUse: Combine 10 Crackling Shards to create a Storm Vessel that may free Alunira from her prison.\n\"Even when idle, the wrath of a storm hums and snaps beneath its surface.\"" }
entries[224026] = { ["name"] = "Storm Vessel", ["text"] = "Binds to Warband\nUse: Removes the Protective Stormshroud from Alunira.\n\"Capable of storing vast amounts of storm energy.\"" }
