entries[224038] = { ["name"] = "Smithing After Saronite", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Blacksmithing Knowledge by 10.\nRequires Khaz Algar Blacksmithing (1)\n\"A small, worn pamphlet instructing nerubian smiths how to adapt to working with more mundane materials instead of the saronite they once worked. Might be useful for blacksmiths.\"\nSell Price:" }
entries[224039] = { ["name"] = "Bottomless Bag of Khaz Algar Tailoring Goods", ["text"] = "Binds when picked up\n\"Contains nearly everything to craft anything, assuming you're a Tailor.\"\n<Right Click to Open>" }
entries[224040] = { ["name"] = "Bottomless Bag of Khaz Algar Optional Goods", ["text"] = "Binds when picked up\n\"Contains all of the stuff you could choose to ignore, but decided not to.\"\n<Right Click to Open>" }
entries[224041] = { ["name"] = "Holy Brigade", ["text"] = "Binds when picked up\nUse: Throw a dollop of holy oil that creates an explosion dealing 29775 Holy Fire damage to all enemies within 6 yards, knocking them back and reducing movement speed by 30% for 8 sec.\n\nKnock back is more effective against enemy players." }
entries[224042] = { ["name"] = "Voracious Residue", ["text"] = "Binds when picked up\nUse: Fog beast residue imbues you, increasing your damage by 5% for 30 sec." }
entries[224043] = { ["name"] = "Famished Residue", ["text"] = "Binds when picked up\nUse: Fog beast residue imbues you, increasing Versatility by 10% for 30 sec." }
entries[224044] = { ["name"] = "Devouring Residue", ["text"] = "Binds when picked up\nUse: Fog beast residue imbues you, reducing damage taken by 15% for 30 sec." }
entries[224045] = { ["name"] = "Kelp Grasp", ["text"] = "Binds when picked up\nUse: Roots all enemies within 6 yards in place for 15 sec. Damage may interrupt the effect. Targets that are rooted take 10% increased damage from you." }
entries[224046] = { ["name"] = "Sand Tornado", ["text"] = "Binds when picked up\nUse: Douse enemies within 10 yards around you in sand dealing 278825 Nature damage and slowing by 40% and reducing their chance to critically strike by 15% for 6 sec." }
entries[224047] = { ["name"] = "Water Blast", ["text"] = "Binds when picked up\nUse: Knocks back the current enemy target, dealing 174266 Frost damage. Knockback is more effective against players." }
entries[224048] = { ["name"] = "Electric Shock", ["text"] = "Binds when picked up\nUse: Deal 46925 Nature damage, knocking enemies back and slowing them by 30% for 8 sec." }
entries[224049] = { ["name"] = "Web Pull", ["text"] = "Binds when picked up\nUse: Pulls an enemy within 40 yards towards the caster, temporarily stunning them." }
entries[224050] = { ["name"] = "Web Sparkles: Pretty and Powerful", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Enchanting Knowledge by 10.\nRequires Khaz Algar Enchanting (1)\n\"A promotional package detailing a value proposition for enchanting one's personal webbing. Potentially useful for enchanters.\"\nSell Price:" }
entries[224051] = { ["name"] = "Slightly Chewed Harvest Bounty", ["text"] = "Quest Item\n\"Still good for a stew or a pie...\"" }
entries[224052] = { ["name"] = "Clocks, Gears, Sprockets, and Legs", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Engineering Knowledge by 10.\nRequires Khaz Algar Engineering (1)\n\"A surprisingly insightful book introducing engineering concepts to nerubian children. Still might be useful to engineers.\"\nSell Price:" }
entries[224053] = { ["name"] = "Eight Views on Defense against Hostile Runes", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Inscription Knowledge by 10.\nRequires Khaz Algar Inscription (1)\n\"Subtitled \"Lessons from the Fall of Ahn-Kahet,\" this tome examines potential ways to disrupt and deflect the runic power of the Lich King and his servants. Might be useful to scribes.\"\nSell Price:" }
entries[224054] = { ["name"] = "Emergent Crystals of the Surface-Dwellers", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Jewelcrafting Knowledge by 10.\nRequires Khaz Algar Jewelcrafting (1)\n\"A freshly printed pamphlet theorizing about use of Resonance Crystals in nerubian gemwork. Useful for jewelcrafters.\"\nSell Price:" }
entries[224055] = { ["name"] = "A Rocky Start", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Mining Knowledge by 10.\nRequires Khaz Algar Mining (1)\n\"A tome of nerubian mining techniques aimed at a journeyman learning the craft. Useful for miners.\"\nSell Price:" }
entries[224056] = { ["name"] = "Uses for Leftover Husks (After You Take Them Apart)", ["text"] = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Leatherworking Knowledge by 10.\nRequires Khaz Algar Leatherworking (1)\n\"A grisly tome discussing productive mutilation of corpses to create useful leather works. It includes ways to use husks of both Alliance and Horde races. Useful for non-squeamish leatherworkers.\"\nSell Price:" }
entries[224057] = { ["name"] = "Professor Instructaur's Top Secret Guide to Khaz Algar Alchemy", ["text"] = "Binds when picked up\nUnique\nUse: Gain 1000 Specialization Points for Khaz Algar Alchemy.\nRequires Khaz Algar Alchemy (15)\n\"You feel like a filthy cheater just holding this, but surely nobody will judge you for taking a peek.\"" }
