entries[224068] = { ["name"] = "Professor Instructaur's Brain Pertaining to Khaz Algar", ["text"] = "Binds when picked up\nUnique\nUse: Set the skill of all Khaz Algar professions you know to their maximum value and teaches you all associated recipes. (2 Min Cooldown)\n\"And now you know why Associate Professor Instructaur has been helping you all this time.\"" }
