entries[224098] = { ["name"] = "Crimson Charmer", ["text"] = "Quest Item\n\"Aemyra told me this is her favorite flower, because she loves its red hue.\"" }
entries[224099] = { ["name"] = "Amber Bloom", ["text"] = "Quest Item\n\"The Arathi say that Amber Bloom reminds them of their star, Beledar. I think they look like Eliza's Decision Sprockets.\"" }
entries[224100] = { ["name"] = "Bottomless Bag of Khaz Algar General Goods", ["text"] = "Binds when picked up\n\"Contains many common reagents shared between all professions. Still missing something? Check a nearby vendor!\"\n<Right Click to Open>" }
