entries[224104] = { ["name"] = "Flashfire Thurible", ["text"] = "Quest Item\nUse: A holy fire thurible that reveals and stuns Nightshade Abductors in Rambleshire. (2 Sec Cooldown)\n\"A small, fragile, glass orb that creates a tremendous flash and bang when shattered.\"" }
