entries[224118] = { ["name"] = "Nightshade Letter", ["text"] = "Quest Item\n\"This letter makes mention of some \"new friends\" that are working with the Order of Night in the area.\"\n<Right Click to Read>" }
entries[224119] = { ["name"] = "Electric Eel", ["text"] = "\"Dead, but still twitching from its inherent electrical charge. These eels are a favorite food of cloudrooks and stormrooks.\"" }
