entries[224146] = { ["name"] = "Khaz Algar Archaeological Fragments", ["text"] = "Quest Item\n\"A piece of Khaz Algar's history. It may not be whole, but a piece is better than no piece.\"" }
entries[224147] = { ["name"] = "Reins of the Sureki Skyrazor", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The skyrazor was one of the most vicious abominations to emerge from Queen Ansurek's experiments with the Black Blood of the Old Gods.\"\nDrop:\nQueen Ansurek\nZone:\nNerub-ar Palace" }
entries[224148] = { ["name"] = "Retrained Skyrazor", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"One of a handful of skyrazors captured by Arathi forces during the Sureki offensive after Queen Ansurek's downfall, this beast has found great use in sniffing out void corruption at home and abroad.\"\nVendor:\nMaterialist Ophinell\nZone:\nTwilight Highlands\nCost:\n100" }
entries[224150] = { ["name"] = "Siesbarg", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Poor guy.\"\nWorld Quest:\nConsolation Flies\nZone:\nAzj-Kahet\nZone:\nCity of Threads" }
entries[224151] = { ["name"] = "Reins of the Ascendant Skyrazor", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Intended for the most devoted of the Sureki elite, these skyrazors were favored by Queen Ansurek for both their cunning and brutality.\"\nDrop:\nQueen Ansurek\nZone:\nNerub-ar Palace (Mythic)" }
entries[224152] = { ["name"] = "Recipe: Empress' Farewell", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Empress' Farewell.\nRecipe for 3 servings. Actual number of servings will vary based on cooking skill.\nRequires Khaz Algar Cooking (35)\nSell Price:" }
