entries[224251] = { ["name"] = "Memory Chord", ["text"] = "Binds when picked up\nToy\nUse: Release a memory of yourself. (5 Min Cooldown)\n\"Drawn from a lifetime of memories.\"\nSell Price:" }
entries[224252] = { ["name"] = "Calcified Journal", ["text"] = "Quest Item\n\"Wrenching this book open reveals that the central pages are largely intact. They are full of sketches of an unfamiliar landscape.\"" }
entries[224253] = { ["name"] = "Elementally Active Coal", ["text"] = "Quest Item\n\"Even now, small chunks of coal tumble aggressively at you if unsecured.\"" }
entries[224254] = { ["name"] = "Wooden Figure", ["text"] = "Quest Item\n\"A roughly carved statuette. It depicts a lynx running through flames.\"" }
entries[224256] = { ["name"] = "Bag of Angry Fungus", ["text"] = "Binds when picked up\nUse: Release a bag full of angry fungus, sure to damage and distract all enemies nearby for 30 sec.\n\nUsable in Light's Blooming and the nearby keyflame areas. (1 Min Cooldown)\n\"The bag is quite restless.\"" }
entries[224257] = { ["name"] = "Sturdy Locket", ["text"] = "Quest Item\n\"Where a portrait normally sits instead contains a flower pressed and preserved between glass.\"" }
entries[224259] = { ["name"] = "Flash", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[224260] = { ["name"] = "Thundo", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[224261] = { ["name"] = "Gale", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[224262] = { ["name"] = "Begrudgingly Poured Cinderbrew", ["text"] = "Quest Item\n\"As searingly hot as Innkeeper Brax's ire. Tastes better, though.\"" }
entries[224263] = { ["name"] = "Infused Fire-Honey Milk", ["text"] = "Binds when picked up\nUnique\nReceiving fatal damage allows you to have one final drink, granting a shield that absorbs damage equal to 25% of your max health for 15 sec. While the shield holds, your Primary Stat is increased by 2553 .\n\nThis effect can only occur once every 5 min while in the outdoors of Khaz Algar.\nSell Price:" }
entries[224264] = { ["name"] = "Deepgrove Petal", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 1.\nRequires Khaz Algar Herbalism (1)" }
entries[224265] = { ["name"] = "Deepgrove Rose", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 4.\n\"You suspect it will be a while before you find a fully grown Deepgrove Rose again.\"" }
entries[224266] = { ["name"] = "Ivory Tinderbox", ["text"] = "Binds when picked up\n\"An ornate tinderbox made from an unknown ivory source. There is a noble figure carved into the lid.\"" }
entries[224267] = { ["name"] = "Dented Spearhead", ["text"] = "Binds when picked up\n\"This battleworn spearhead is attached to a chain. It appears to be a trophy of some sort.\"" }
entries[224268] = { ["name"] = "Filigreed Cleric", ["text"] = "Binds when picked up\n\"While the design of this Light's Gambit piece suggests it was intended to be decorative, it holds quite a bit of wear and tear.\"" }
entries[224270] = { ["name"] = "Tattered Technique: Certificate of Ownership", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Tattered Certificate of Ownership.\nRequires Classic Inscription (1)\nSell Price:\nTattered Certificate of Ownership\nClasses: Hunter\n\"A deed to a pet well-loved.\"\nSell Price:\nRequires Light Parchment , Celestial Ink (2)" }
entries[224271] = { ["name"] = "Galvanic Gland", ["text"] = "Quest Item\n\"Machine Speakers in rural regions have learned to use these as temporary batteries.\"" }
entries[224272] = { ["name"] = "Calcified Journal", ["text"] = "Binds when picked up\n\"Wrenching this book open reveals that the central pages are largely intact. They are full of sketches of an unfamiliar landscape.\"" }
entries[224273] = { ["name"] = "Wooden Figure", ["text"] = "Binds when picked up\n\"A roughly carved statuette. It depicts a lynx running through flames.\"" }
entries[224274] = { ["name"] = "Sturdy Locket", ["text"] = "Binds when picked up\n\"Where a portrait normally sits instead contains a flower pressed and preserved between glass.\"" }
entries[224278] = { ["name"] = "Timewarped Ironforge Blueprints", ["text"] = "Quest Item\nUnique" }
entries[224283] = { ["name"] = "Reclaimed Catalyst", ["text"] = "Quest Item\n\"Moderately toxic, but just imagine the colors!\"" }
entries[224284] = { ["name"] = "Eyeless Petal", ["text"] = "Quest Item\n\"Almost vibrant enough to be worth navigating the spikes.\"" }
entries[224285] = { ["name"] = "Luminous Strangler Sap", ["text"] = "Quest Item\n\"How else would you achieve the perfect dewy glow?\"" }
entries[224286] = { ["name"] = "Cochineal Crawler", ["text"] = "Quest Item\n\"Alas, its beauty was its downfall.\"" }
entries[224290] = { ["name"] = "Storm Defender's Axe", ["text"] = "Binds to Warband until equipped\nOne-Hand Axe\n798 - 1,658 Damage Speed 2.60\n(472.3 damage per second)\n+415 [Agility or Strength]\n+1,730 Stamina\nDurability 90 / 90\nEquip: Your damaging spells have a chance to cast Chain Lightning between 3 enemies, dealing 23641 Nature damage to each of them.\nSell Price:" }
entries[224292] = { ["name"] = "Radiant Fuel Shard", ["text"] = "Binds when picked up\nUnique (45)\nDuration: 15 min (real time)\nUse: Turn three Radiant Fuel Shards into Radiant Fuel Crystal." }
entries[224294] = { ["name"] = "Shiny Rock or Sweetmeat", ["text"] = "Quest Item" }
entries[224296] = { ["name"] = "Basket of Draconic Flowers", ["text"] = "Binds when picked up\nUnique\n\"Originally harvested for use in magical fireworks, these flowers have latent magical energies. Open to receive a flower from each of the five dragonflights!\"\n<Right Click to Open>" }
entries[224297] = { ["name"] = "Dreamsurge Cradle", ["text"] = "Binds when picked up\n\"This glimmering pod can be exchanged for a piece of Dreambound gear of your choosing from Archdruid Hamuul Runetotem near Dreamsurge Investigations.\"\nSell Price:" }
entries[224298] = { ["name"] = "Dilated Eon Canister", ["text"] = "Binds when picked up\n\"Eternally filling, never full.\"" }
entries[224300] = { ["name"] = "Gleeful Glamour - Blood Elf", ["text"] = "Use: Don the mask, magically altering your appearance to that of another one of Azeroth's residents.\n\nLasts 20-60 min. based on the quality of the Gleeful Glamour.\nSell Price:" }
