entries[224373] = { ["name"] = "Waterlord's Iridescent Gem", ["text"] = "\"An array of colors swirls and swims inside. Your touch excites whatever is living inside, churning quicker as if to break free.\"\nSell Price:" }
entries[224374] = { ["name"] = "Reins of the Thundering Ruby Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Thundering Ruby Cloud Serpent. This is a flying mount. Requires Cloud Serpent Riding from the Order of the Cloud Serpent.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"From their infancy, Thundering Cloud Serpents are drawn to storms. They have been known to chase lightning through the blackened, roiling clouds, and to bathe in the pouring rain.\"\nDrop:\nAlani\nZone:\nVale of Eternal Blossoms" }
entries[224395] = { ["name"] = "Secret Garlic", ["text"] = "Quest Item\n\"How do these grow here?\"" }
entries[224396] = { ["name"] = "Mangled Taro", ["text"] = "Quest Item\n\"Well, you tried.\"" }
entries[224397] = { ["name"] = "Pristine Taro", ["text"] = "Quest Item\n\"Starchy perfection.\"" }
entries[224398] = { ["name"] = "Reins of the Frayfeather Hippogryph", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This majestic hippogryph hails from the Frayfeather Highlands of Feralas. Though it previously protected its hatchlings, now it chooses to serve a greater cause.\"\nVendor:\nBobadormu\nZone:\nTanaris\nCost:\n5000\n\nVendor:\nGrannadormu\nZone:\nTanaris\nCost:\n5000" }
entries[224399] = { ["name"] = "Reins of the Amani Hunting Bear", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Amani trolls ride this fierce creature on ceremonial hunts in honor of the bear god Nalorakk.\"\nVendor:\nCupri\nZone:\nShattrath City\nCost:\n5000" }
entries[224400] = { ["name"] = "See Where Running Candles", ["text"] = "Quest Item\n\"You can't flee if you can't see.\"" }
entries[224401] = { ["name"] = "Run Far Food", ["text"] = "Quest Item\n\"Supplies for the road.\"" }
entries[224402] = { ["name"] = "Krafting Tools", ["text"] = "Quest Item\n\"Needed both for clearing escape tunnels and rebuilding homes.\"" }
entries[224403] = { ["name"] = "Heirloom Wax", ["text"] = "Quest Item\n\"Passed down through the generations, this wax is a living, gooey history of the tribe.\"" }
