entries[224415] = { ["name"] = "Ivory Goliathus", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These giant beetles spend their lives in the darkest tunnels of Khaz Algar. Though they are deprived even of the faintest glimmer of artificial sunlight, they still thrive.\"\nAchievement:\nGlory of the Delver" }
