entries[224752] = { ["name"] = "Soaked Journal Entry", ["text"] = "Binds to Warband\nUse: Increase Fishing skill by 10, up to a max of 300.\nRequires level 68 to 80 ( 80)\n\"Barely legible but perhaps of use to someone in your Warband.\"\nSell Price:" }
