entries[224756] = { ["name"] = "Cookie's Special Flavors", ["text"] = "Binds when picked up\nHeld In Off-hand\n+5 Intellect\n+2 Stamina\n+ 1 Critical Strike\n+ 2 Versatility\nSell Price:" }
