entries[224758] = { ["name"] = "Stolen Stormwind Helmet", ["text"] = "Binds when picked up\nHead Plate\n7 Armor\n+3 [Strength or Intellect]\n+4 Stamina\n+ 2 Haste\n+ 3 Versatility\nDurability 85 / 85\nSell Price:" }
entries[224759] = { ["name"] = "Pirate's Bracers", ["text"] = "Binds when picked up\nWrist Leather\n2 Armor\n+1 [Agility or Intellect]\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Haste\nDurability 50 / 50\nSell Price:" }
entries[224760] = { ["name"] = "Wobbles", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion." }
entries[224761] = { ["name"] = "Quickwick Candle Kit", ["text"] = "Binds when picked up\nUse: Place a wax copy of yourself at your current location. (40 Sec Cooldown)\n\"This candle kit can be used to make several small candles. Or one large wax figure.\"" }
entries[224762] = { ["name"] = "Delver's Waterskin", ["text"] = "Use: Restores ( 375000 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\nSell Price:" }
entries[224763] = { ["name"] = "Design: Cubic Blasphemia", ["text"] = "Use: Teaches you how to craft Cubic Blasphemia.\nHigh quality Cubic Blasphemia cuts require specializing in the gemcutting techniques of the four most coveted gemstones found on Khaz Algar. Even a cheap knock-off takes a mastered technique.\nRequires Khaz Algar Jewelcrafting (50)\nSell Price:" }
entries[224764] = { ["name"] = "Mosswool Thread", ["text"] = "Crafting Reagent\n\"Spun from the wool of the Isle of Dorn's sheep, this thread is both durable and versatile. Sold by Tailoring vendors.\"\nSell Price:" }
entries[224765] = { ["name"] = "Everburning Ignition", ["text"] = "Binds when picked up\nUnique (10)\nUse: Ignite the forge.\n\nGain Ingenuity, Multicraft, and Resourcefulness based on your Everburning Forge specialization for 10 min.\n\"Siphoned from your expertise with the forge.\"\nSell Price:" }
entries[224766] = { ["name"] = "Faithful Dog", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[224767] = { ["name"] = "Giant Candle Parts", ["text"] = "\"The wax here is supposed to be useful to Dagran. Perhaps he'll write a good thesis doctorate on the effects of wax on the bags of adventurers.\"" }
entries[224768] = { ["name"] = "Delver's Dirigible Schematic: Wing-Mounted Propeller", ["text"] = "Delver's Dirigible Schematic: Wing-Mounted Propeller\nAirship Schematic\nBinds when picked up\nUnique\nUse: Unlocks this customization option for the Delver's Dirigible at the Rostrum of Transformation." }
entries[224769] = { ["name"] = "Delver's Dirigible Schematic: Rotor Blades", ["text"] = "Airship Schematic\nBinds when picked up\nUnique\nUse: Unlocks this customization option for the Delver's Dirigible at the Rostrum of Transformation." }
entries[224770] = { ["name"] = "Delver's Dirigible Schematic: Front-Mounted Propeller", ["text"] = "Delver's Dirigible Schematic: Front-Mounted Propeller\nAirship Schematic\nBinds when picked up\nUnique\nUse: Unlocks this customization option for the Delver's Dirigible at the Rostrum of Transformation." }
entries[224771] = { ["name"] = "Delver's Dirigible Schematic: Empennage", ["text"] = "Airship Schematic\nBinds when picked up\nUnique\nUse: Unlocks this customization option for the Delver's Dirigible at the Rostrum of Transformation." }
entries[224772] = { ["name"] = "Bounty from Gallywix", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 80 to 80 ( 80)\n\"These orders describe a large bounty available to any of the Darkfuse that discover who is responsible for opening the wall at Opportunity Point.\"" }
entries[224773] = { ["name"] = "Knicknack's Red Candle", ["text"] = "Quest Item\n\"A candle of deep red wax. You don't want to know how the kobolds got that color.\"" }
entries[224774] = { ["name"] = "Knicknack's Potion Bottle", ["text"] = "Quest Item\n\"A slick, indeterminate liquid coats the inside of this glass bottle.\"" }
entries[224775] = { ["name"] = "Knicknack's Definitely Rubies", ["text"] = "Quest Item\n\"A pair of uncut red gems. They seem to be of moderate quality and whether or not they are rubies is unclear.\"" }
entries[224777] = { ["name"] = "Sureki Shadecaster", ["text"] = "Quest Item\nUnique\n\"Nerubians use these emitters to project orders and messages from their high-ranking leaders.\"" }
entries[224778] = { ["name"] = "Knicknack's Enbiggener", ["text"] = "Quest Item\n\"The Enbiggener appears to be an earthen jewel crafting tool, used for magnification purposes.\"" }
entries[224779] = { ["name"] = "Alhainr's Skull", ["text"] = "Quest Item\n\"Small leaves and vines sprout from the skull.\"" }
entries[224780] = { ["name"] = "Toughened Tempest Pelt", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Skinning Knowledge by 1.\n\"A particularly rugged pelt that isn't pliable enough to use in crafting. You could study it to learn a thing or two about the local fauna, however.\"" }
entries[224781] = { ["name"] = "Abyssal Fur", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Skinning Knowledge by 2.\n\"A small tuft of fur that carries a deep purple hue. It isn't of much traditional use, but such a fascinating and rare specimen won't be found very often.\"" }
entries[224782] = { ["name"] = "Razor Talon", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Skinning Knowledge by 1.\n\"A small, but extremely sharp talon of a creature. While it isn't big enough to be of practical use, it is fascinating to study.\"" }
entries[224783] = { ["name"] = "Sovereign's Finery Chest", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Set down a chest of royal clothes for you and others to try on. (1 Hour Cooldown)\n\"Only for those with the most exquisite taste.\"\nSell Price:" }
entries[224784] = { ["name"] = "Pinnacle Cache", ["text"] = "Binds when picked up\n\"Weekly cache containing materials for upgrading gear, gold, Adventurer gear, and more.The first four weekly caches you earn each week contain Coffer Key Shards.\"\n<Right Click to Open>" }
entries[224786] = { ["name"] = "Skeleton King Outfit", ["text"] = "Binds when picked up\nUnique\nUse: Transform into the Skeleton King. (3 Sec Cooldown)" }
entries[224791] = { ["name"] = "Golden Lord Outfit", ["text"] = "Binds when picked up\nUnique\nUse: Transform into a Golden Lord. (3 Sec Cooldown)" }
entries[224792] = { ["name"] = "Sanguine Aristocrat Outfit", ["text"] = "Binds when picked up\nUnique\nUse: Transform into a Sanguine Aristocrat. (3 Sec Cooldown)" }
entries[224797] = { ["name"] = "Zirdo's Ledger", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 80 to 80 ( 80)\n\"The ledger contains deliveries of Black Blood across the Undermine that were approved by Noggenfogger, Trade-Prince of the Steamwheedle Cartel.\"" }
entries[224799] = { ["name"] = "Nizrek's potion", ["text"] = "Quest Item\nUnique\nUse: Restores the vitality of an ally. (2 Sec Cooldown)\n\"A vial of faintly glowing liquid.\"" }
entries[224800] = { ["name"] = "Orbinid Pigment", ["text"] = "Crafting Reagent\n\"A pigment milled by players with the Inscription skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224801] = { ["name"] = "Orbinid Pigment", ["text"] = "Crafting Reagent\n\"A pigment milled by players with the Inscription skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
