entries[224803] = { ["name"] = "Blossom Pigment", ["text"] = "Crafting Reagent\n\"A pigment milled by players with the Inscription skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224804] = { ["name"] = "Blossom Pigment", ["text"] = "Crafting Reagent\n\"A pigment milled by players with the Inscription skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224805] = { ["name"] = "Blossom Pigment", ["text"] = "Crafting Reagent\n\"A pigment milled by players with the Inscription skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224807] = { ["name"] = "Algari Skinner's Notes", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Skinning Knowledge by 3." }
entries[224808] = { ["name"] = "Opal Ore", ["text"] = "Quest Item\nUnique (20)\n\"Crucial pieces of a lost puzzle.\"" }
entries[224809] = { ["name"] = "Earthen Plumber's Pipe", ["text"] = "Binds when picked up\nUse: Reroute water through the ancient pipe system to clear the blockage. (3 Sec Cooldown)\nSell Price:" }
entries[224810] = { ["name"] = "Woodworm Elixir", ["text"] = "Quest Item\nUnique\n\"Made from wood-boring worms. Famous in the City of Threads, despite being nigh undrinkable.\"" }
entries[224811] = { ["name"] = "Sugar Shrooms", ["text"] = "Binds when picked up\nUnique (20)\nUse: The fungal essence transforms your shape and increases haste by 25% for 30 sec.\n\nUsable in Light's Blooming and the nearby keyflame areas. (30 Sec Cooldown)\nRequires Renown Rank 12 with the Hallowfall Arathi.\n\"Kids absolutely love hunting for these sweet delights!\"\nSell Price:" }
entries[224813] = { ["name"] = "Big Cat Whistle", ["text"] = "Binds when picked up\nUnique (20)\nUse: Summon a large Battle Lynx to aid you in combat for 5 min.\n\nUsable in Light's Blooming and the nearby keyflame areas. (5 Min Cooldown)\nRequires Renown Rank 12 with the Hallowfall Arathi.\n\"The biggest lynx are always just a whistle away.\"\nSell Price:" }
entries[224814] = { ["name"] = "Adventurer's Warbound Boots", ["text"] = "The War Within Season 1\nBinds when picked up\nUnlocked by progressing the Season 1 Delver's Journey.\n\"Contains an Adventurer 4/8 piece of equipment corresponding to your class.\"\nSell Price:" }
entries[224815] = { ["name"] = "Charm of the Flame", ["text"] = "Binds when picked up\nUnique (20)\nUse: Imbue yourself with the sacred flame, causing your attacks and abilities to occasionally spawn an elemental of light which inflicts 3 Holy damage to targets.\n\nUsable in Light's Blooming and nearby keyflame areas.\nRequires Renown Rank 12 with the Hallowfall Arathi.\n\"The dwindling supply of these is rapidly being exhausted by the Arathor.\"\nSell Price:" }
entries[224816] = { ["name"] = "Nerubian Almanac", ["text"] = "\"Indistinguishable charts and diagrams fill the pages. The only discernable thing seems to be an illustration of seismic waves that outline a tunnel system below.\"\nSell Price:" }
entries[224817] = { ["name"] = "Algari Herbalist's Notes", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 3." }
entries[224818] = { ["name"] = "Algari Miner's Notes", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Mining Knowledge by 3." }
entries[224822] = { ["name"] = "Scour Through Scrap", ["text"] = "\"Rummage through scrap to find parts, forgotten prototypes, and more!\"" }
entries[224824] = { ["name"] = "Duskweave", ["text"] = "Crafting Reagent\n\"A shadow-infused cloth sourced by Tailors from humanoids throughout Khaz Algar. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224826] = { ["name"] = "Dawnweave", ["text"] = "Crafting Reagent\n\"A light-infused cloth sourced by Tailors from humanoids throughout Khaz Algar. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224828] = { ["name"] = "Weavercloth", ["text"] = "Crafting Reagent\n\"A sticky cloth sourced by Tailors from humanoids throughout Khaz Algar. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224831] = { ["name"] = "Cube of Infinite Inventions (PTR Only)", ["text"] = "Binds when picked up\nUnique\nUse: Reset the cooldown of Khaz Algar Engineering cooldowns.\n\nThis item is purely for testing purposes.\nRequires Khaz Algar Engineering (1)\n\"Counts as a samophlange, whatever that is.\"" }
entries[224832] = { ["name"] = "Exquisite Weavercloth Bolt", ["text"] = "Crafting Reagent\n\"An artisan bolt of cloth crafted by Tailors. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224833] = { ["name"] = "Exquisite Weavercloth Bolt", ["text"] = "Crafting Reagent\n\"An artisan bolt of cloth crafted by Tailors. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224834] = { ["name"] = "Exquisite Weavercloth Bolt", ["text"] = "Crafting Reagent\n\"An artisan bolt of cloth crafted by Tailors. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[224835] = { ["name"] = "Deepgrove Roots", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 1.\n\"The roots continue to grow even after the rose is plucked. Not useful for any practical purposes, but rather intriguing to study.\"" }
entries[224837] = { ["name"] = "Cursed Pickaxe", ["text"] = "Binds to Warband until equipped\nOne-Hand Axe\n1,180 - 2,452 Damage Speed 2.60\n(698.5 damage per second)\n+614 [Agility or Strength]\n+3,002 Stamina\n+ 424 Critical Strike\n+ 170 Haste\nDurability 90 / 90\nWhile this item is in your bags, equipped, or being used for transmog you will occasionally be consumed by the curse.\n\"Ancient runes decorate the metal head and trail onto the handle in the form of carved etchings. These patterns become more erratic as they reach the pommel, eventually becoming nothing more than frantic scratches.\"\nSell Price:" }
entries[224838] = { ["name"] = "Null Sliver", ["text"] = "Binds when picked up\nUse: Study to increase your Khaz Algar Mining Knowledge by 1.\n\"The tiniest sliver of null stone which radiates a pulsing aura of emptiness. It isn't particularly useful for any crafts, but studying it could teach you more about Algari ore and minerals.\"" }
entries[224839] = { ["name"] = "Adventurer's Warbound Wrists", ["text"] = "The War Within Season 1\nBinds when picked up\nUnlocked by progressing the Season 1 Delver's Journey.\n\"Contains an Adventurer 4/8 piece of equipment corresponding to your class.\"\nSell Price:" }
entries[224840] = { ["name"] = "Adventurer's Warbound Waist", ["text"] = "The War Within Season 1\nBinds when picked up\nUnlocked by progressing the Season 1 Delver's Journey.\n\"Contains an Adventurer 4/8 piece of equipment corresponding to your class.\"\nSell Price:" }
entries[224841] = { ["name"] = "Adventurer's Warbound Shoulders", ["text"] = "The War Within Season 1\nBinds when picked up\nUnlocked by progressing the Season 1 Delver's Journey.\n\"Contains an Adventurer 4/8 piece of equipment corresponding to your class.\"\nSell Price:" }
